from collections import defaultdict
import json

def solve(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    output = [[bg]*w for _ in range(h)]

    specials = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                specials[grid[r][c]].append((r, c))

    for color, points in specials.items():
        if len(points) == 1:
            r0, c0 = points[0]
            offset = c0 - r0
            for r in range(h):
                c = r + offset
                if 0 <= c < w:
                    output[r][c] = color
        elif len(points) >= 2:
            points_list = list(points)
            n = len(points_list)
            for i in range(n):
                for j in range(i+1, n):
                    r1, c1 = points_list[i]
                    r2, c2 = points_list[j]
                    dr, dc = r2 - r1, c2 - c1

                    if dr == 0 or dc == 0 or abs(dr) != abs(dc):
                        continue

                    steps = abs(dr)
                    for k in range(steps + 1):
                        r = int(r1 + k * dr / steps)
                        c = int(c1 + k * dc / steps)
                        output[r][c] = color

    return output

