bg = 4
h, w = len(demo_input), len(demo_input[0])

# DESCENDING: 6 fills first (protects itself), 1 overwrites 6
def transform_descending(grid):
    result = [[bg]*w for _ in range(h)]
    specials = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                color = grid[r][c]
                if color not in specials:
                    specials[color] = []
                specials[color].append((r, c))

    for color in reversed(sorted(specials.keys())):  # 6 first, then 1
        for r0, c0 in specials[color]:
            const = r0 - c0
            for r in range(h):
                c = r - const
                if 0 <= c < w:
                    result[r][c] = color
    return result

